def _peel(paths):
    """Peel peripheral links simultaneously.

    Returns (all_links, rounds, surviving path records).
    """
    info = {}
    cand = set()
    all_links = set()

    def refresh(link):
        st = info[link]
        if st[0] > 0 and (st[1] == 0 or st[2] == 0):
            cand.add(link)
        else:
            cand.discard(link)

    def add(path, sign):
        first = path[0]
        last = path[-1]
        for i in range(len(path) - 1):
            link = _canon(path[i], path[i + 1])
            st = info.get(link)
            if st is None:
                st = info[link] = [0, 0, 0]
            st[0] += sign
            a = path[i]
            b = path[i + 1]
            if a != first and a != last:
                if link[0] == a:
                    st[1] += sign
                else:
                    st[2] += sign
            if b != first and b != last:
                if link[0] == b:
                    st[1] += sign
                else:
                    st[2] += sign
            refresh(link)

    for path, _count in paths:
        for i in range(len(path) - 1):
            all_links.add(_canon(path[i], path[i + 1]))
        add(path, 1)

    current = list(paths)
